select 
from stu_permission_template


        and (
            template_code like concat('%', #{keyword}, '%')
            or template_name like concat('%', #{keyword}, '%')
        )


        and status = #{status}


        and study_mode = #{studyMode}


        and product_id = #{productId}


        and class_id = #{classId}


order by id desc
